```javascript
// AWS Secrets Manager example
const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager({ region: 'us-east-1' });

async function loadProductionSecrets() {
  try {
    const data = await secretsManager.getSecretValue({ SecretId: 'my-app-secrets' }).promise();
    return JSON.parse(data.SecretString);
  } catch (error) {
    console.error('Failed to load secrets:', error);
    process.exit(1);
  }
}

// Usage
loadProductionSecrets().then(secrets => {
  process.env.DATABASE_URL = secrets.DATABASE_URL;
  process.env.API_KEY = secrets.API_KEY;
  // ... other secrets
});
```

#### Option B: Kubernetes Secrets
```javascript
// For Kubernetes deployments
const path = require('path');

function getSecret(secretName) {
  const secretPath = `/run/secrets/${secretName}`;
  try {
    return require('fs').readFileSync(secretPath, 'utf8').trim();
  } catch (e) {
    console.error(`Failed to read secret ${secretName}:`, e.message);
    return null;
  }
}

// Usage
