#### Option C: HashiCorp Vault
```javascript
// HashiCorp Vault example
const vault = require('node-vault');

const client = vault({
  endpoint: process.env.VAULT_ADDR, // 'http://127.0.0.1:8200'
  token: process.env.VAULT_TOKEN
});

async function getSecret(path) {
  try {
    const data = await client.read(path);
    return data.data;
  } catch (error) {
    console.error('Vault error:', error);
    throw error;
  }
}

// Usage
async function loadSecrets() {
  const dbSecrets = await getSecret('secret/data/database');
  const apiSecrets = await getSecret('secret/data/api');

  process.env.DATABASE_URL = dbSecrets.connectionString;
  process.env.API_KEY = apiSecrets.key;
}
```

