  | "intermediate"
  | "sophisticated"
  | "all";
const model = values.model!;
const repetitions = parseInt(values.repetitions!, 10);
const defence = values.defence!;
const backend = (values.backend === "bedrock" ? "bedrock" : "ollama") as
  | "ollama"
  | "bedrock";
// Per-backend defaults — empty string from CLI means "use the
// IntentTracker's default for the chosen backend".
const embeddingModel =
  values["embedding-model"] ||
  (backend === "bedrock" ? "eu.cohere.embed-v4:0" : "nomic-embed-text");
const judgeModel =
  values["judge-model"] ||
  (backend === "bedrock" ? "eu.anthropic.claude-sonnet-4-6" : "llama3.2");
const thetaWarn = parseFloat(values["theta-warn"]!);
const thetaBlock = parseFloat(values["theta-block"]!);
const deltaWarn = parseFloat(values["delta-warn"]!);

const outputPath =
  values.output ||
  join(
    import.meta.dirname,
    "..",
    "results",
    `results-${defence}-${new Date().toISOString().replace(/[:.]/g, "-")}.json`
  );

function createLogger(): TurnLogger {
  switch (defence) {
    case "none":
      return new TurnLogger();

    case "drift-only":
      return new IntentTracker({
        backend,
        embeddingModel,
        judgeModel,
        thetaWarn: 999, // never trigger judge
        thetaBlock,
        deltaWarn: 999, // never trigger judge
        enableGoalAnchoring: false,
        enableBlocking: true, // block only on extreme drift
      });

    case "intent-tracker":
      return new IntentTracker({
        backend,
        embeddingModel,
        judgeModel,
        thetaWarn,
        thetaBlock,
        deltaWarn,
        enableGoalAnchoring: true,
        enableBlocking: true,
      });

    case "anchor-only":
      return new IntentTracker({
        backend,
        embeddingModel,
        judgeModel,
        thetaWarn,
        thetaBlock: 999, // never hard-block
        deltaWarn,
        enableGoalAnchoring: true,
        enableBlocking: false,
      });

    case "promptarmor-obs":
    case "promptarmor": {
      // Observational PromptArmor — the agent receives the original
      // tool output unchanged, but every output is screened against
      // /screen and the verdict is recorded. T-2 Path C from
      // docs/plan-promptarmor-test-framework-2026-05-13.md.
      const url = values["promptarmor-url"];
      if (!url) {
        console.error(
          `Defence ${defence} requires --promptarmor-url (e.g. https://judge-ai-dredd-interactive.aisandbox.dev.ckotech.internal)`,
        );
        process.exit(1);
      }
      return new PromptArmorObserver({
        dreddUrl: url,
        backend: (values["promptarmor-backend"] || "bedrock") as "bedrock" | "openai",
        model: values["promptarmor-model"] || "eu.anthropic.claude-sonnet-4-6",
        runId: values["promptarmor-run-id"] || undefined,
        apiKey: values["promptarmor-api-key"] || process.env.DREDD_API_KEY || undefined,
        insecure: values["promptarmor-insecure"] === true,
      });
    }

    default:
      console.error(`Unknown defence: ${defence}`);
      console.error(
        "Options: none, drift-only, anchor-only, intent-tracker, promptarmor-obs",
      );
      process.exit(1);
  }
}

