  console.log(`TEST: ${scenario.id} — ${scenario.name}`);
  console.log(`MODEL: ${model} → ${bedrockModel}`);
  console.log(`SOPHISTICATION: ${scenario.sophistication}`);
  console.log(`WORKSPACE: ${workDir}`);
  console.log(`${"═".repeat(70)}`);

