        } else {
          reject(err);
        }
      });

      srv.listen(this._port, "127.0.0.1", () => {
        this.server = srv;
        this._startedAt = new Date().toISOString();
        resolve();
      });
    });
  }

  async stop(): Promise<void> {
    if (!this.server) return;
    return new Promise((resolve) => {
      this.server!.close(() => {
        this.server = null;
        resolve();
      });
    });
  }

