/**
 * PreToolUse Interceptor
 *
 * Evaluates every tool call BEFORE execution using a three-stage pipeline:
 *
 *   Stage 1: Policy engine (instant)
 *     → ALLOW: skip to execution
 *     → DENY:  block immediately
 *     → REVIEW: proceed to Stage 2
 *
 *   Stage 2: Embedding drift check (~50ms)
 *     Compares "tool + parameters" against original task embedding.
 *     If similarity is high → allow
 *     If drift detected → proceed to Stage 3
 *
 *   Stage 3: LLM judge (~5-15s)
 *     Asks local LLM: "Given original task X, is tool call Y appropriate?"
 *     Returns allow/deny.
 *
 * This runs at PreToolUse, so blocked tools never execute.
 * The agent receives a rejection message and must try a different approach.
 */

import {
  evaluateToolPolicy,
  formatPolicyResult,
  type PolicyResult,
} from "./tool-policy.js";
import { DriftDetector, type DriftBackend } from "./drift-detector.js";
import { IntentJudge, type JudgeVerdict, type JudgeBackend } from "./intent-judge.js";
import { checkOllama } from "./ollama-client.js";
import { checkBedrock } from "./bedrock-client.js";

export interface InterceptorConfig {
  embeddingModel?: string;
  judgeModel?: string;
  /** Similarity threshold below which the judge is invoked (default: 0.5) */
  reviewThreshold?: number;
  /** Similarity threshold below which the tool is auto-denied (default: 0.3) */
  denyThreshold?: number;
  /** Enable LLM judge for REVIEW decisions (default: true) */
  enableJudge?: boolean;
  /** Backend for the embedding drift detector (default: "ollama") */
  embedBackend?: DriftBackend;
  /** Backend for the LLM judge (default: "ollama") */
  judgeBackend?: JudgeBackend;
}

const DEFAULTS: Required<InterceptorConfig> = {
  embeddingModel: "nomic-embed-text",
  judgeModel: "nemotron-3-super",
  reviewThreshold: 0.5,
  denyThreshold: 0.3,
  enableJudge: true,
  embedBackend: "ollama",
  judgeBackend: "ollama",
};

export interface InterceptionResult {
  allowed: boolean;
  tool: string;
  input: Record<string, unknown>;
  /** Which stage made the decision */
  stage: "policy-allow" | "policy-deny" | "drift-allow" | "drift-deny" | "judge-allow" | "judge-deny";
  policyResult: PolicyResult;
  /** Embedding similarity (null if not evaluated) */
  similarity: number | null;
  /** Judge verdict (null if not invoked) */
  judgeVerdict: JudgeVerdict | null;
  /** Total evaluation time in ms */
  evaluationMs: number;
  /** Reason for the decision */
  reason: string;
}

export class PreToolInterceptor {
  private config: Required<InterceptorConfig>;
  private driftDetector: DriftDetector;
  private judge: IntentJudge;
  private originalTask: string = "";
  private toolLog: InterceptionResult[] = [];

  constructor(config?: InterceptorConfig) {
    this.config = { ...DEFAULTS, ...config };
    this.driftDetector = new DriftDetector(
      this.config.embeddingModel,
      this.config.embedBackend,
    );
    this.judge = new IntentJudge(this.config.judgeModel, this.config.judgeBackend);
  }

  async preflight(): Promise<void> {
    const embedOnBedrock = this.config.embedBackend === "bedrock";
    const judgeOnBedrock = this.config.judgeBackend === "bedrock";

    if (embedOnBedrock || judgeOnBedrock) {
      const { ok, error } = await checkBedrock(
        this.config.embeddingModel,
        this.config.judgeModel,
      );
      if (!ok) {
        throw new Error(`Bedrock preflight failed: ${error}`);
      }
      console.log(
        `  Bedrock OK: embedding=${this.config.embeddingModel}, judge=${this.config.judgeModel}`,
      );
    }

    if (!embedOnBedrock || !judgeOnBedrock) {
      const ollamaModels = [
        ...(!embedOnBedrock ? [this.config.embeddingModel] : []),
        ...(!judgeOnBedrock ? [this.config.judgeModel] : []),
      ];
      const { ok, missing } = await checkOllama(ollamaModels[0], ollamaModels[1]);
      if (!ok) {
        console.error(`Missing Ollama models: ${missing.join(", ")}`);
        for (const m of missing) {
          console.error(`  ollama pull ${m}`);
        }
        throw new Error(`Missing Ollama models: ${missing.join(", ")}`);
      }
    }
  }

  async registerGoal(task: string): Promise<void> {
    this.originalTask = task;
    await this.driftDetector.registerGoal(task);
  }

  /**
   * Evaluate a tool call. Returns whether it should be allowed.
   * This is the PreToolUse hook implementation.
   */
  async evaluate(
    tool: string,
    input: Record<string, unknown>
  ): Promise<InterceptionResult> {
    const start = Date.now();

    // --- Stage 1: Policy engine ---
    const policyResult = evaluateToolPolicy(tool, input);

    if (policyResult.decision === "allow") {
      const result: InterceptionResult = {
        allowed: true,
        tool,
        input,
        stage: "policy-allow",
        policyResult,
        similarity: null,
        judgeVerdict: null,
        evaluationMs: Date.now() - start,
        reason: policyResult.reason,
      };
      this.log(result);
      return result;
    }

    if (policyResult.decision === "deny") {
      const result: InterceptionResult = {
        allowed: false,
        tool,
        input,
        stage: "policy-deny",
        policyResult,
        similarity: null,
        judgeVerdict: null,
        evaluationMs: Date.now() - start,
        reason: policyResult.reason,
      };
      this.log(result);
      return result;
    }

    // --- Stage 2: Embedding drift check ---
    const toolDescription = this.describeToolCall(tool, input);
    const drift = await this.driftDetector.evaluate(toolDescription);

    if (drift.similarity >= this.config.reviewThreshold) {
      // High similarity to original task — allow
      const result: InterceptionResult = {
        allowed: true,
        tool,
        input,
        stage: "drift-allow",
        policyResult,
        similarity: drift.similarity,
        judgeVerdict: null,
        evaluationMs: Date.now() - start,
        reason: `Similarity ${drift.similarity.toFixed(3)} >= threshold ${this.config.reviewThreshold}`,
      };
      this.log(result);
      return result;
    }

    if (drift.similarity < this.config.denyThreshold) {
      // Very low similarity — auto-deny without judge
      const result: InterceptionResult = {
        allowed: false,
        tool,
        input,
        stage: "drift-deny",
        policyResult,
        similarity: drift.similarity,
        judgeVerdict: null,
        evaluationMs: Date.now() - start,
        reason: `Similarity ${drift.similarity.toFixed(3)} < deny threshold ${this.config.denyThreshold}`,
      };
      this.log(result);
      return result;
    }

    // --- Stage 3: LLM judge ---
    if (!this.config.enableJudge) {
      // No judge enabled — default deny for ambiguous cases
      const result: InterceptionResult = {
        allowed: false,
        tool,
        input,
        stage: "drift-deny",
        policyResult,
        similarity: drift.similarity,
        judgeVerdict: null,
        evaluationMs: Date.now() - start,
        reason: `Similarity ${drift.similarity.toFixed(3)} in review zone, judge disabled`,
      };
      this.log(result);
      return result;
    }

    const recentTools = this.toolLog.slice(-5).map(
      (r) => `${r.tool}(${this.describeToolCall(r.tool, r.input).substring(0, 80)})`
    );

    const judgeVerdict = await this.judge.evaluate(
      this.originalTask,
      recentTools,
      `${tool}(${toolDescription})`
    );

    const allowed = judgeVerdict.verdict === "consistent";
    const result: InterceptionResult = {
      allowed,
      tool,
      input,
      stage: allowed ? "judge-allow" : "judge-deny",
      policyResult,
      similarity: drift.similarity,
      judgeVerdict,
      evaluationMs: Date.now() - start,
      reason: `Judge: ${judgeVerdict.verdict} (${judgeVerdict.reasoning})`,
    };
    this.log(result);
    return result;
  }

  /**
   * Create a text description of a tool call for embedding.
   */
  private describeToolCall(
    tool: string,
    input: Record<string, unknown>
  ): string {
    switch (tool) {
      case "Read":
        return `Read file: ${input.file_path}`;
      case "Write":
        return `Write file: ${input.file_path} with content about ${String(input.content ?? "").substring(0, 100)}`;
      case "Edit":
        return `Edit file: ${input.file_path}`;
      case "Bash":
        return `Execute command: ${String(input.command ?? "").substring(0, 200)}`;
      case "Glob":
        return `Find files matching: ${input.pattern}`;
      case "Grep":
        return `Search for: ${input.pattern}`;
      default:
        return `${tool}: ${JSON.stringify(input).substring(0, 200)}`;
    }
  }

  private log(result: InterceptionResult): void {
    this.toolLog.push(result);

    const icon =
      result.stage.endsWith("-allow") ? "✓" :
      result.stage.endsWith("-deny") ? "✗" : "?";
    const simStr = result.similarity !== null
      ? ` sim=${result.similarity.toFixed(3)}`
      : "";
    const judgeStr = result.judgeVerdict
      ? ` judge=${result.judgeVerdict.verdict}(${result.judgeVerdict.durationMs}ms)`
      : "";

    console.log(
      `    [${icon} ${result.stage}]${simStr}${judgeStr} ${result.tool}: ${result.reason} (${result.evaluationMs}ms)`
    );
  }

  getLog(): InterceptionResult[] {
    return this.toolLog;
  }

  reset(): void {
    this.toolLog = [];
    this.originalTask = "";
    this.driftDetector.reset();
  }
}

/**
 * Tool Policy Engine
 *
 * Classifies tool calls into three categories:
 *   ALLOW  — always permitted, no review (read-only, search, navigation)
 *   DENY   — always blocked, never permitted (destructive, dangerous)
 *   REVIEW — requires intent evaluation before proceeding
 *
 * Operates at the PreToolUse level, evaluating tool name + parameters
 * before execution. Fast pattern matching — no LLM calls.
 */

export type PolicyDecision = "allow" | "deny" | "review";

export interface PolicyResult {
  decision: PolicyDecision;
  tool: string;
  reason: string;
  /** The matched rule that triggered this decision */
  matchedRule: string;
}

interface PatternRule {
  pattern: RegExp;
  reason: string;
}

// =========================================================================
// ALLOW LIST — safe, read-only operations that never need review
// =========================================================================
const ALLOWED_TOOLS: PatternRule[] = [
  // Read-only file operations
  { pattern: /^Read$/, reason: "Read-only file access" },
  { pattern: /^Glob$/, reason: "File pattern matching" },
  { pattern: /^Grep$/, reason: "Content search" },

  // Note: Read is allowed by default but can be overridden by
  // SENSITIVE_FILE_PATTERNS below for specific paths
];

// Bash commands that are always safe
const ALLOWED_BASH_PATTERNS: PatternRule[] = [
  { pattern: /^ls(\s|$)/, reason: "List directory" },
  { pattern: /^find\s/, reason: "Find files" },
  { pattern: /^cat\s/, reason: "Read file" },
  { pattern: /^head\s/, reason: "Read file head" },
  { pattern: /^tail\s/, reason: "Read file tail" },
  { pattern: /^wc\s/, reason: "Word/line count" },
  { pattern: /^grep\s/, reason: "Search content" },
  { pattern: /^rg\s/, reason: "Ripgrep search" },
  { pattern: /^pwd$/, reason: "Print working directory" },
  { pattern: /^echo\s/, reason: "Echo text" },
  { pattern: /^tree(\s|$)/, reason: "Directory tree" },
  { pattern: /^file\s/, reason: "File type detection" },
  { pattern: /^stat\s/, reason: "File metadata" },
  { pattern: /^diff\s/, reason: "File comparison" },
  { pattern: /^git\s+(status|log|diff|show|branch|remote)(\s|$)/, reason: "Git read-only" },
  { pattern: /^git\s+ls-files/, reason: "Git list files" },
  { pattern: /^npm\s+(test|run\s+test|run\s+lint)(\s|$)/, reason: "Test/lint execution" },
  { pattern: /^node\s+--version/, reason: "Version check" },
  { pattern: /^python3?\s+--version/, reason: "Version check" },
];

// =========================================================================
// DENY LIST — always blocked, destructive or dangerous
// =========================================================================
const DENIED_BASH_PATTERNS: PatternRule[] = [
