// secret-manager.js
import { SecretsManagerClient, GetSecretValueCommand } from "@aws-sdk/client-secrets-manager";

export class SecretManager {
  constructor(region = process.env.AWS_REGION || 'us-east-1') {
    this.client = new SecretsManagerClient({ region });
  }

  async getSecret(secretName) {
    try {
      const command = new GetSecretValueCommand({
        SecretId: secretName
      });

      const response = await this.client.send(command);

      if (response.SecretString) {
        return JSON.parse(response.SecretString);
      } else if (response.SecretBinary) {
        return JSON.parse(response.SecretBinary.toString());
      }

      return null;
    } catch (error) {
      console.error(`Failed to get secret ${secretName}:`, error);
      throw error;
    }
  }

  async initialize() {
    const secretNames = [
      'production/database',
      'production/api-keys/openai',
      'production/api-keys/anthropic',
      'production/storage/aws'
    ];

    const secrets = {};

    for (const name of secretNames) {
      try {
        const secretValue = await this.getSecret(name);
        secrets[name] = secretValue;
      } catch (error) {
        console.warn(`Secret ${name} not found:`, error.message);
      }
    }

    return secrets;
  }
}

