// Add this before the server creation
const rateLimitMap = new Map();
const RATE_LIMIT_WINDOW = 60000; // 1 minute
const RATE_LIMIT_MAX_REQUESTS = 100;

function checkRateLimit(ip) {
    const now = Date.now();
    const clientData = rateLimitMap.get(ip) || { count: 0, windowStart: now };

    if (now - clientData.windowStart > RATE_LIMIT_WINDOW) {
        clientData.count = 1;
        clientData.windowStart = now;
    } else {
        clientData.count++;
    }

    rateLimitMap.set(ip, clientData);
    return clientData.count <= RATE_LIMIT_MAX_REQUESTS;
}

// In the server handler, add this near the beginning:
const clientIp = req.socket.remoteAddress || req.connection.remoteAddress || 'unknown';
