      await this.client.send(
        new PutCommand({
          TableName: this.tableName,
          Item: {
            pk: pk(sessionId),
            sk: "META",
            gsi1pk: GSI_PK,
            gsi1sk: meta.startedAt ?? new Date().toISOString(),
            ttl: ttl(),
            version: 1,
            ...meta,
