#### 1. **Add Validation to .env.local Loader**
```javascript
// Add this validation before accepting any env var
const ALLOWED_SECRET_PATTERNS = [
    /^CLERK_.*$/i,
    /^AWS_.*$/i,
    /^OLLAMA_.*$/i,
    /^BEDROCK_.*$/i,
    /^S3_.*$/i,
    /^DREDD_.*$/i,
    /^REDIS_.*$/i,
    /^DATABASE_.*$/i,
    /^JWT_.*$/i,
    /^TOKEN_.*$/i,
    /^API_KEY.*$/i,
];

const DENIED_NAMES = [
    'LD_PRELOAD', 'LD_LIBRARY_PATH', 'PATH', 'LIBRARY_PATH',
    'BASH_FUNC', 'ENV', 'FUNCTIONS'
];

function isValidSecretName(name) {
    if (DENIED_NAMES.includes(name.toUpperCase())) {
        throw new Error(`Environment variable name ${name} is forbidden`);
    }

    return ALLOWED_SECRET_PATTERNS.some(pattern => pattern.test(name));
}
```

#### 2. **Implement Secret Rotation with Health Checks**
```javascript
