app.get('/health/secrets', async (req, res) => {
    const secretFiles = [
        '/etc/secrets/clerk-secret',
        '/etc/secrets/aws-credentials'
    ];

    const secretCheck = await Promise.all(
        secretFiles.map(file => 
            checkSecretFile(file)
        )
