        location: 'Environment variable',
        pattern: /^pk_live_[a-zA-Z0-9]+$/i,
        required: true,
        rotationNote: 'If compromised, rotate in Clerk dashboard',
    },
    {
        name: 'CLERK_JWT_PUBLIC_KEY',
        description: 'Clerk JWT public key for offline verification',
        location: 'Environment variable (PEM or JWK format)',
        pattern: /^-----BEGIN PUBLIC KEY-----|^\{.*"kty":"RSA".*\}$/,
        required: false,
        rotationNote: 'Yearly rotation required; rotate in Clerk dashboard',
    },
    {
        name: 'AWS_ACCESS_KEY_ID',
        description: 'AWS access key for Bedrock/DynamoDB',
        location: 'Environment variable (avoid) / IAM Role (preferred)',
        pattern: /^(AKIA|ASIA|GPA|IDA|ROA|IPA|NPA|NVA)[0-9A-Z]{16}$/i,
        required: true,
        rotationNote: 'IAM roles auto-rotate; access keys rotate every 90 days',
    },
    {
        name: 'AWS_SECRET_ACCESS_KEY',
        description: 'AWS secret key for Bedrock/DynamoDB',
        location: 'Environment variable (avoid) / IAM Role (preferred)',
        pattern: /^[A-Za-z0-9\/+=]{40}$/,
        required: true,
        rotationNote: 'Never share; auto-rotate with IAM roles',
    },
    {
        name: 'AWS_SESSION_TOKEN',
        description: 'AWS temporary session token',
        location: 'Environment variable',
        pattern: /^[A-Za-z0-9\/+=]+$/i,
        required: false,
        rotationNote: 'Auto-rotates with IAM roles',
    },
    {
        name: 'BEDROCK_REGION',
        description: 'AWS region for Bedrock services',
        location: 'Environment variable',
        pattern: /^(us|eu|ap|sa|ca|me|af|ap-southeast|ap-northeast|eu-west|eu-central|us-east|us-west|sa-east|ca-central)-(1|2|3|4|5)$/,
        required: false,
        rotationNote: 'Not a secret, but should be verified',
    },
    {
        name: 'OLLAMA_HOST',
        description: 'Ollama server endpoint',
        location: 'Environment variable',
        pattern: /^https?:\/\/[a-zA-Z0-9.\-]+(?::\d+)?\/?$/i,
        required: false,
        rotationNote: 'If self-hosted, ensure internal network only',
    },
    {
        name: 'DynamoDB TableName',
        description: 'DynamoDB table name for sessions/data',
        location: 'Code / Configuration',
        pattern: /^jaid-(sessions|api-keys|approvals)$/,
        required: true,
        rotationNote: 'Not a secret, but should be documented',
    },
    {
        name: 'API Keys',
        description: 'Internal API keys for hook authentication',
        location: 'Database (hashed)',
        pattern: /^jaid_live_[A-Za-z0-9]{43}$/,
        required: true,
        rotationNote: 'Generated with 256-bit entropy; rotate per user',
    },
    {
        name: 'Webhook URLs',
        description: 'External webhook endpoints',
        location: 'Environment variable',
        pattern: /^https?:\/\/[a-zA-Z0-9.\-]+\/[^\s]+$/i,
        required: false,
        rotationNote: 'External service URLs; rotate if compromised',
