    LOW: ['OLLAMA_HOST', 'BEDROCK_REGION', 'DynamoDB TableName', 'API Keys'],
};

/**
 * Scan a file for secret references (NOT values)
 */
function scanFile(filePath: string): { file: string; references: string[] } | null {
    if (!existsSync(filePath)) return null;

    try {
        const content = readFileSync(filePath, 'utf8');
        const patternrefs: string[] = [];

        for (const pattern of SECRET_PATTERNS) {
            const regex = new RegExp(pattern.name, 'g');
            if (regex.test(content)) {
                patternrefs.push(pattern.name);
            }
        }

        return {
            file: filePath,
            references: [...new Set(patternrefs)],
        };
