    for (const dir of directoriesToScan) {
        if (existsSync(dir)) {
            const files = getAllFiles(dir);
            filesScanned.push(...files);

            for (const file of files) {
                const result = scanFile(file);
                if (result && result.references.length > 0) {
                    filesWithSecrets.push(result);
                }
            }
        }
    }

    console.log(`Files scanned: ${filesScanned.length}`);
    console.log(`Files referencing secrets: ${filesWithSecrets.length}`);
    console.log();

    // Group by severity
    const bySeverity: {[key: string]: typeof SECRET_PATTERNS} = {
        CRITICAL: [],
        HIGH: [],
        MEDIUM: [],
        LOW: [],
    };

    for (const pattern of SECRET_PATTERNS) {
        if (SEVERITY_ASSESSMENT.HIGH.includes(pattern.name)) {
            bySeverity.CRITICAL.push(pattern);
