    const severityLabels = {
        CRITICAL: '🔴 CRITICAL (Immediate rotation required)',
        HIGH: '🟠 HIGH (Rotation recommended)',
        MEDIUM: '🟡 MEDIUM (Monitor and plan rotation)',
        LOW: '🟢 LOW (Routine rotation)',
    };

    for (const severity of severityOrder) {
        const patterns = bySeverity[severity];
        if (patterns.length > 0) {
            console.log(severityLabels[severity]);
            console.log('-'.repeat(80));

            for (const pattern of patterns) {
                console.log();
                console.log(`📋 ${pattern.name}`);
