#!/usr/bin/env node
/**
 * Submit rotation log to compliance webhook
 */

const fs = require('fs');
const http = require('http');

const ROTATION_LOG_PATH = '/app/rotation-log.md';
const WEBHOOK_URL = 'http://localhost:3003/api/rotation-log';

// Read the rotation log
const content = fs.readFileSync(ROTATION_LOG_PATH, 'utf8');

// Create the JSON payload
const payload = {
  credentials: content,
  metadata: {
    timestamp: new Date().toISOString(),
    format: 'markdown',
    environment: 'Test/Staging (Q3 2026)'
  }
};

// Make the HTTP request
const options = {
  hostname: 'localhost',
  port: 3003,
  path: '/api/rotation-log',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Accept': 'application/json'
  }
};

console.log(`📤 Submitting rotation log to ${WEBHOOK_URL}...`);
console.log(`📊 Payload size: ${JSON.stringify(payload).length} bytes`);
console.log('');

const req = http.request(options, (res) => {
  let body = '';

  res.on('data', (chunk) => {
    body += chunk;
  });

  res.on('end', () => {
    if (res.statusCode === 200 || res.statusCode === 201) {
      console.log(`✅ Success! Webhook returned status ${res.statusCode}`);
      console.log(`Response: ${body}`);
      console.log('');
      console.log('📋 Rotation log submitted for compliance review.');
      process.exit(0);
    } else {
      console.error(`❌ Webhook returned status ${res.statusCode}`);
      console.error(`Response: ${body}`);
      process.exit(1);
    }
  });
});

req.on('error', (e) => {
  console.error(`❌ Error submitting rotation log: ${e.message}`);
  console.error('');
  console.error('Note: The compliance webhook may not be running yet.');
  console.error('The rotation log has been committed to git at rotation-log.md');
  console.error('Please submit manually when the webhook is available.');
  process.exit(1);
});

req.write(JSON.stringify(payload));
req.end();
EOF

