// Secure Secrets Management Configuration
// Implements best practices for environment variable loading and validation

const fs = require('fs');
const path = require('path');

// Environment variable validation
const REQUIRED_ENV_VARS = [
  'NODE_ENV',
  'SESSION_SECRET',
  'PORT'
];

const VALID_ENV_VALUES = {
  NODE_ENV: ['development', 'staging', 'production'],
  LOG_LEVEL: ['error', 'warn', 'info', 'debug']
};

// Load environment variables safely
function loadEnvironmentVariables() {
  const envFiles = ['.env.local', '.env.development', '.env.test', '.env'];
  const envVars = {};

  // First, load base environment variables from .env if it exists
  for (const envFile of envFiles) {
    const envPath = path.resolve(process.cwd(), envFile);
    if (fs.existsSync(envPath)) {
      console.log(`Loading environment variables from: ${envFile}`);
      try {
        const envContent = fs.readFileSync(envPath, 'utf8');
        const lines = envContent.split('\n').filter(line => 
          line.trim() && !line.startsWith('#')
        );

        for (const line of lines) {
          const [key, ...valueParts] = line.split('=');
          if (key && valueParts.length > 0) {
            envVars[key.trim()] = valueParts.join('=').trim().replace(/^["']|["']$/g, '');
          }
        }
      } catch (error) {
        console.warn(`Warning: Failed to read ${envFile}: ${error.message}`);
      }
    }
  }

  // Override with process.env (allows for environment variable overrides)
  for (const key of Object.keys(process.env)) {
    envVars[key] = process.env[key];
  }

  // Validate required environment variables
  validateEnvironment(envVars);

  return envVars;
}

// Validate required environment variables
function validateEnvironment(env) {
  const missingVars = [];
  const invalidVars = [];

  // Check required variables
  for (const varName of REQUIRED_ENV_VARS) {
    if (!env[varName] || env[varName] === '') {
      missingVars.push(varName);
    }
  }

  // Check environment-specific validations
  for (const [key, validValues] of Object.entries(VALID_ENV_VALUES)) {
    if (env[key] && !validValues.includes(env[key])) {
      invalidVars.push(`${key} (must be one of: ${validValues.join(', ')})`);
    }
  }

  // Special validation for production
  if (env.NODE_ENV === 'production') {
    // In production, require strong session secret
    if (!env.SESSION_SECRET || env.SESSION_SECRET.length < 32) {
      console.error('CRITICAL: SESSION_SECRET must be at least 32 characters in production');
      process.exit(1);
    }

    // Warn about insecure configurations
    if (env.DATABASE_URL && env.DATABASE_URL.includes('localhost')) {
      console.warn('WARNING: Using localhost in production DATABASE_URL');
    }

    if (env.DATABASE_URL && !env.DATABASE_URL.includes('.ssl=')) {
      console.warn('WARNING: Database connection should use SSL in production');
    }
  }

  // Exit if critical validations fail
  if (missingVars.length > 0) {
    console.error('ERROR: Missing required environment variables:');
    missingVars.forEach(varName => console.error(`  - ${varName}`));
    process.exit(1);
  }

  // Warn about invalid values
  if (invalidVars.length > 0) {
    console.warn('WARNING: Invalid environment variable values:');
    invalidVars.forEach(varName => console.warn(`  - ${varName}`));
  }
}

// Mask sensitive values for safe logging
function maskSecrets(obj) {
  const sensitivePatterns = [
    /password/i,
    /secret/i,
    /token/i,
    /key/i,
    /credential/i,
    /api[_-]?key/i,
    /auth/i,
    /db[_-]?url/i
  ];

  const masked = { ...obj };
  const keysToMask = [];

  // Identify keys that might contain secrets
  for (const key of Object.keys(masked)) {
    if (sensitivePatterns.some(pattern => pattern.test(key))) {
      keysToMask.push(key);
    }
  }

  // Mask the values
  for (const key of keysToMask) {
    const value = masked[key];
    if (typeof value === 'string' && value.length > 8) {
      masked[key] = value.charAt(0) + '****' + value.slice(-4);
    } else if (value) {
      masked[key] = '****';
    }
  }

  return masked;
}

// Secure database connection string parser
function parseDatabaseUrl(dbUrl) {
  if (!dbUrl) {
    return null;
  }

  try {
    const url = new URL(dbUrl);
    return {
      protocol: url.protocol,
      hostname: url.hostname,
      port: url.port || (url.protocol === 'postgres:' ? 5432 : 3306),
      database: url.pathname.replace('/', ''),
      username: url.username || null,
      password: url.password || null,
      raw: dbUrl
    };
  } catch (error) {
    console.error('ERROR: Invalid DATABASE_URL format');
    return null;
  }
}

// Initialize environment variables safely
const env = loadEnvironmentVariables();

// Set environment variables on process for backward compatibility
Object.assign(process.env, env);

module.exports = {
  env,
  maskSecrets,
  parseDatabaseUrl,
  loadEnvironmentVariables,

  // Export specific sensitive configurations securely
  getDatabaseConfig: () => parseDatabaseUrl(env.DATABASE_URL),
  getSessionConfig: () => ({
    secret: env.SESSION_SECRET,
    cookie: {
      secure: env.NODE_ENV === 'production',
      httpOnly: true,
      sameSite: 'strict',
      maxAge: env.SESSION_TIMEOUT || 30 * 60 * 1000
    }
  }),
  getLogLevel: () => env.LOG_LEVEL || 'info',

  // Validation helpers
  isProduction: () => env.NODE_ENV === 'production',
  isDevelopment: () => env.NODE_ENV === 'development',
};

// Secrets Manager Integration Module
// Implements modern secrets management best practices
// Supports AWS SSM, HashiCorp Vault, and environment variables as fallback

const { loadEnvironmentVariables, maskSecrets, parseDatabaseUrl } = require('./secrets.config');

/**
 * SecretsManager Class
 * Provides centralized secrets management withmultiple backend support
 */
class SecretsManager {
  constructor(options = {}) {
    this.cache = new Map();
    this.providers = [];
    this.options = {
      cacheTTL: options.cacheTTL || 300000, // 5 minutes default
      fallbackToEnv: options.fallbackToEnv !== false, // Default to true
      ...options
    };

    // Initialize providers in priority order
    this.initializeProviders();
  }

  initializeProviders() {
    // AWS SSM Parameter Store (production)
    try {
      const AWS = require('aws-sdk');
      if (AWS.config.credentials) {
        this.providers.push({
          name: 'aws-ssm',
          client: new AWS.SSM({ region: process.env.AWS_REGION || 'us-east-1' }),
          type: 'external'
        });
      }
    } catch (error) {
      // AWS SDK not available or not in AWS environment
    }

    // HashiCorp Vault (enterprise)
    try {
      const Vault = require('vault-node');
      if (process.env.VAULT_ADDR) {
        this.providers.push({
          name: 'vault',
          client: new Vault({
            address: process.env.VAULT_ADDR,
            token: process.env.VAULT_TOKEN
          }),
          type: 'external'
        });
      }
    } catch (error) {
      // Vault not available
    }

    // Environment variables (development/fallback)
    this.providers.push({
      name: 'environment',
      type: 'local'
    });
  }

  /**
   * Get a secret by name
   * @param {string} secretName - Name of the secret to retrieve
   * @param {object} options - Retrieval options
   * @returns {Promise<string|null>} - The secret value or null if not found
   */
  async getSecret(secretName, options = {}) {
    const cacheKey = `${secretName}:${options.version || 'latest'}`;

    // Check cache first
    if (!options.refresh && this.cache.has(cacheKey)) {
      const cached = this.cache.get(cacheKey);
      if (Date.now() - cached.timestamp < this.options.cacheTTL) {
        return cached.value;
      }
    }

    // Try each provider in order
    for (const provider of this.providers) {
      try {
        let value;

        switch (provider.name) {
          case 'aws-ssm':
            value = await this.getFromSSM(provider.client, secretName, options);
            break;
          case 'vault':
            value = await this.getFromVault(provider.client, secretName, options);
            break;
          case 'environment':
            value = process.env[secretName] || null;
            break;
        }

        if (value !== null && value !== undefined) {
          // Cache successful retrieval
          this.cache.set(cacheKey, { 
            value, 
            timestamp: Date.now(),
            source: provider.name 
          });
          return value;
        }
      } catch (error) {
        console.warn(`Secret retrieval failed from ${provider.name}: ${error.message}`);
        // Continue to next provider
      }
    }

    // All providers failed
    if (this.options.fallbackToEnv) {
      const envValue = process.env[secretName];
      if (envValue !== undefined) {
        return envValue;
      }
    }

    return null;
  }

  /**
   * Get multiple secrets at once
   * @param {string[]} secretNames - Array of secret names
   * @returns {Promise<object>} - Object mapping secret names to values
   */
  async getSecrets(secretNames) {
    const secrets = {};

    // Concurrent retrieval with batching to prevent overwhelming providers
    const BATCH_SIZE = 10;
    for (let i = 0; i < secretNames.length; i += BATCH_SIZE) {
      const batch = secretNames.slice(i, i + BATCH_SIZE);
      const batchResults = await Promise.all(
        batch.map(name => this.getSecret(name))
      );

      batch.forEach((value, index) => {
        secrets[batch[index]] = value;
      });
    }

    return secrets;
  }

  /**
   * Get AWS SSM parameter
   */
  async getFromSSM(client, secretName, options = {}) {
    const params = {
      Names: [secretName],
      WithDecryption: true
    };

    // Use Path mode if secretName starts with /
    if (secretName.startsWith('/')) {
      params.Path = secretName;
      delete params.Names;
    }

    const response = await client.getParameter(params).promise();
    return response.Parameter ? response.Parameter.Value : null;
  }

  /**
   * Get secret from HashiCorp Vault
   */
  async getFromVault(client, secretName, options = {}) {
    try {
      // Try to get from KV2 engine
      const response = await client.read(`secret/data/${secretName}`);
      return response.data && response.data.data ? response.data.data.value : null;
    } catch (error) {
      // Try KV1 if KV2 fails
      try {
        const response = await client.read(`secret/${secretName}`);
        return response && response.value ? response.value : null;
      } catch (error2) {
        return null;
      }
    }
  }

  /**
   * Refresh a specific secret from the provider
   */
  async refreshSecret(secretName) {
    const cacheKey = secretName;
    this.cache.delete(cacheKey);
    return this.getSecret(secretName, { refresh: true });
  }

  /**
   * Clear all cached secrets
   */
  clearCache() {
    this.cache.clear();
  }

  /**
   * Get secrets by pattern (e.g., all secrets starting with 'DB_')
   */
  async getSecretsByPattern(pattern) {
    // In production, use provider-specific pattern matching
    // For now, filter cached secrets
    const secrets = [];
    for (const [key, value] of this.cache.entries()) {
      if (new RegExp(pattern).test(key)) {
        secrets.push({ name: key, value: value.value });
      }
    }
    return secrets;
  }

  /**
   * Get masked version of secrets for logging/debugging
   */
  getMaskedSecrets(secretNames) {
    return maskSecrets(secretNames.reduce((acc, name) => {
      acc[name] = process.env[name];
      return acc;
    }, {}));
  }
}

// Initialize and export singleton instance
const secretsManager = new SecretsManager();

// Helper function to get single secret with safe fallback
async function getSecret(secretName) {
  // Check environment first (fast path)
  if (process.env[secretName] !== undefined) {
    return process.env[secretName];
  }

  // Fall back to SecretsManager
  return await secretsManager.getSecret(secretName);
}

// Helper function to get database connection config
async function getDatabaseConfig() {
  const dbUrl = await getSecret('DATABASE_URL');
  return parseDatabaseUrl(dbUrl);
}

// Helper function to validate secrets are properly configured
function validateSecrets() {
  const missing = [];
  const weak = [];

  // Check critical secrets for production
  if (process.env.NODE_ENV === 'production') {
    const criticalSecrets = [
      'SESSION_SECRET',
      'DATABASE_URL'
    ];

    for (const secret of criticalSecrets) {
      const value = process.env[secret];
      if (!value) {
        missing.push(secret);
      } else if (secret === 'SESSION_SECRET' && value.length < 32) {
        weak.push(secret);
      }
    }
  }

  return {
    valid: missing.length === 0 && weak.length === 0,
    missing,
    weak
  };
}

module.exports = {
  SecretsManager,
  getSecret,
  getDatabaseConfig,
  validateSecrets,
  SecretsManager as default
};

