// Secure Express.js application with comprehensive security measures
// Implements OWASP Top 10 best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const session = require('express-session');
const { body, query, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests from this IP, please try again later.' }
});
app.use(limiter);

// Session management
app.use(session({
  secret: process.env.SESSION_SECRET || 'your-secret-key-change-in-production',
  resave: false,
  saveUninitialized: false,
  cookie: {
    secure: process.env.NODE_ENV === 'production',
    httpOnly: true,
    sameSite: 'strict',
    maxAge: 30 * 60 * 1000 // 30 minutes
  },
  rolling: true
}));

// Body parsing with security consideration
app.use(express.json());
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware factory
const validateInput = (validationRules) => {
  return async (req, res, next) => {
    await Promise.all(validationRules.map(rule => rule.run(req)));
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    next();
  };
};

// Authentication middleware
const authenticateUser = (req, res, next) => {
  if (!req.session.user) {
    return res.status(401).json({ error: 'Unauthorized - Authentication required' });
  }
  next();
};

// Authorization middleware (role-based)
const authorizeRole = (requiredRole) => {
  return (req, res, next) => {
    if (!req.session.user || req.session.user.role !== requiredRole) {
      return res.status(403).json({ error: 'Forbidden - Insufficient permissions' });
    }
    next();
  };
};

// Health check endpoint (no authentication required)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Users endpoint with authentication and data minimization
app.get('/users', authenticateUser, async (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
    ];

    const isUserAdmin = req.session.user && req.session.user.role === 'admin';

    // Data minimization - admins see full data, regular users see sanitized data
    if (isUserAdmin) {
      res.json(users.map(user => ({
        id: user.id,
        name: user.name,
        email: user.email,
        role: user.role
      })));
    } else {
      res.json(users.map(user => ({
        id: user.id,
        name: user.name
      })));
    }
  } catch (error) {
    next(error);
  }
});

// Profile endpoint - users can only access their own profile
app.get('/users/:id/profile', authenticateUser, validateInput([
  query('id').isInt({ min: 1 }).toInt()
]), async (req, res) => {
  try {
    const userId = parseInt(req.params.id);
    const currentUserId = req.session.user.id;

    // Authorization check - users can only view their own profile
    if (userId !== currentUserId) {
      return res.status(403).json({ error: 'Forbidden - You can only view your own profile' });
    }

    const user = {
      id: userId,
      name: 'User Name',
      email: 'user@example.com',
      role: 'user'
    };

    res.json({ profile: user });
  } catch (error) {
    next(error);
  }
});

// Login endpoint
app.post('/login', validateInput([
  body('username').isString().trim().escape().notEmpty().withMessage('Username is required'),
  body('password').isString().notEmpty().withMessage('Password is required')
]), async (req, res) => {
  try {
    const { username, password } = req.body;

    // In production, validate against database
    // const user = await User.findOne({ username });
    // const isValidPassword = await bcrypt.compare(password, user.password);

    // Mock authentication for demonstration
    if (username && password) {
      req.session.user = {
        id: 1,
        username: username,
        role: username === 'admin' ? 'admin' : 'user'
      };

      res.json({ 
        success: true, 
        message: 'Login successful',
        user: {
          id: req.session.user.id,
          username: req.session.user.username,
          role: req.session.user.role
        }
      });
    } else {
      res.status(401).json({ error: 'Invalid credentials' });
    }
  } catch (error) {
    next(error);
  }
});

// Logout endpoint
app.post('/logout', authenticateUser, (req, res) => {
  req.session.destroy((err) => {
    if (err) {
      return res.status(500).json({ error: 'Failed to logout' });
    }
    res.json({ success: true, message: 'Logout successful' });
  });
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);

  const isProduction = process.env.NODE_ENV === 'production';

  res.status(err.status || 500).json({
    error: isProduction ? 'Internal Server Error' : err.message,
    ...(isProduction ? {} : { stack: err.stack }),
    ...(err.errors ? { errors: err.errors } : {})
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Security headers middleware (additional custom headers)
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  res.setHeader('Permissions-Policy', 'geolocation=(), microphone=(), camera=()');
  next();
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

