// Initialize secrets
const sessionSecret = process.env.SESSION_SECRET || require('crypto').randomBytes(64).toString('hex');
const sessionTimeout = parseInt(process.env.SESSION_TIMEOUT) || 30 * 60 * 1000;

// Session management
app.use(session({
  secret: sessionSecret,
  resave: false,
  saveUninitialized: false,
  cookie: {
    secure: process.env.NODE_ENV === 'production',
    httpOnly: true,
    sameSite: 'strict',
    maxAge: sessionTimeout
  },
  rolling: true
}));

// Production secrets validation
if (process.env.NODE_ENV === 'production') {
  const { valid, missing, weak } = validateSecrets();
  if (!valid) {
    console.error('❌ Production secrets validation failed:');
    if (missing.length > 0) {
      console.error(`   Missing secrets: ${missing.join(', ')}`);
    }
    if (weak.length > 0) {
      console.error(`   Weak secrets: ${weak.join(', ')}`);
    }
    console.error('   Server will not start in production with invalid secrets.');
    process.exit(1);
  }
}

const PORT = parseInt(process.env.PORT) || 3000;

// Print startup information (without exposing secrets)
const startupInfo = {
  environment: process.env.NODE_ENV || 'development',
  port: PORT,
  secretsValid: process.env.NODE_ENV !== 'production' || validateSecrets().valid,
  usingSecretsManager: true
};
console.log('Starting secure server:', startupInfo);

app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

